function LuckRewardsCell:UpdateUI(index , adId , dialog , isPlay)
    if isNull(isPlay) then
        isPlay = true
    end
    local isRewards = false 
    if checkInt(adId) > 0 then
        ---@type LuckRewardVo
        local luckRewardVo = CfUtils.GetCfVo(AutoIds.IdSetting4080,"LuckRewardVo" ,adId )
        kTool.SetActive(self.RewardNode,true)
        ---@type GoodNodeMB 
        local GoodNodeMB = self.GoodNode.Env
        if isNotNull(GoodNodeMB) then
            GoodNodeMB:Reload({
                goodsId = luckRewardVo.rewards.goodsId,
                isShowNo = true, 
                text =  "x" .. luckRewardVo.rewards.goodsNum   
            })
        end
        GoodNodeMB:SetClickButtonAction(function ()
            local luckRewardVo = CfUtils.GetCfVo(AutoIds.IdSetting4080,"LuckRewardVo" ,adId )
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(luckRewardVo.rewards.goodsId)
            GameUtils.ShowCommonTipsBoard(self.BtnNode, vo.name, vo.desc, vo.quality, vo.id, true)    
        end)
        GoodNodeMB:SetSanXingGainShow(true)
        isRewards = true    
        if isPlay then
            CfUtils.PlayAnimation(self.Root ,"ResidentLuckyRewardDialog2990_Open")     
        end
    else 
        CfUtils.PlayAnimation(self.Root ,"ResidentLuckyRewardDialog2990_UnOpened")     
    end
    SetButtonAction(self.BtnNode , function ()
        if adId == 0 then
            dialog:DrawClick(index)
        end
    end)   
    kTool.SetActive(self.ImgIconLight ,not isRewards)     
end
function LuckRewardsCell:ResidentLuckyRewardDialog2990_Flip()
    CfUtils.PlayAnimation(self.Root ,"ResidentLuckyRewardDialog2990_Flip")
end
function LuckRewardsCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return LuckRewardsCell